from pathlib import Path
import re
page=Path('app/page.tsx');s=page.read_text()
new_modal=r'''function EventModal({clients,event,onClose,onSaved}:any){const allowedStatuses=['preventivo_inviato','confermato','annullato'];const initialStatus=allowedStatuses.includes(event?.status)?event.status:'preventivo_inviato';const [calculated,setCalculated]=useState(0);const [form,setForm]=useState({client_id:event?.client_id||'',event_date:event?.event_date||new Date().toISOString().slice(0,10),service:event?.service||'cena',adults:event?.adults??0,baby:event?.baby??0,status:initialStatus,price_adjustment:event?.price_adjustment??0,price_per_baby:event?.price_per_baby??'',internal_notes:event?.internal_notes||''});const [saving,setSaving]=useState(false);useEffect(()=>{if(!event?.id||!supabase){setCalculated(0);return}(async()=>{const m=await supabase.from('event_menus').select('id').eq('event_id',event.id).eq('active',true).limit(1).maybeSingle();if(!m.data){setCalculated(0);return}const items=await supabase.from('event_menu_items').select('sale_price').eq('menu_id',m.data.id);setCalculated((items.data||[]).reduce((a:any,x:any)=>a+Number(x.sale_price||0),0))})()},[event?.id]);const finalPrice=calculated+Number(form.price_adjustment||0);async function save(e:FormEvent){e.preventDefault();if(!supabase)return;setSaving(true);const payload={client_id:form.client_id||null,event_date:form.event_date,service:form.service,adults:Number(form.adults),baby:Number(form.baby),status:form.status,price_adjustment:Number(form.price_adjustment||0),price_per_adult:finalPrice,price_per_baby:form.price_per_baby===''?null:Number(form.price_per_baby),internal_notes:form.internal_notes};const res=event?await supabase.from('events').update(payload).eq('id',event.id):await supabase.from('events').insert(payload);setSaving(false);if(!res.error){await onSaved();onClose()}else alert(res.error.message)}return <Modal title={event?`Evento #${event.event_number}`:'Nuovo evento'} onClose={onClose} wide><form id="eventMainForm" onSubmit={save} className="formGrid eventForm"><label className="eventClientField">Cliente<select value={form.client_id} onChange={e=>setForm({...form,client_id:e.target.value})}><option value="">Seleziona cliente</option>{clients.map((c:Client)=><option key={c.id} value={c.id}>{nameOfClient(c)}</option>)}</select></label><div className="eventTopRow"><label>Data<input type="date" value={form.event_date} onChange={e=>setForm({...form,event_date:e.target.value})} required/></label><label>Servizio<select value={form.service} onChange={e=>setForm({...form,service:e.target.value})}><option value="pranzo">Pranzo</option><option value="cena">Cena</option><option value="altro">Altro</option></select></label><label>Stato<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="preventivo_inviato">Preventivo inviato</option><option value="confermato">Confermato</option><option value="annullato">Annullato</option></select></label></div><div className="eventPairRow"><label>Adulti<input type="number" min="0" value={form.adults} onChange={e=>setForm({...form,adults:e.target.value as any})}/></label><label>Baby<input type="number" min="0" value={form.baby} onChange={e=>setForm({...form,baby:e.target.value as any})}/></label></div><div className="eventPriceRow"><label>Prezzo calcolato €<input type="text" value={euro(calculated)} readOnly/></label><label>Correttivo €<input type="number" step="0.01" value={form.price_adjustment} onChange={e=>setForm({...form,price_adjustment:e.target.value as any})}/></label><label>Prezzo per persona €<input type="text" value={euro(finalPrice)} readOnly/></label></div><label>Prezzo menu baby €<input type="number" step="0.01" min="0" value={form.price_per_baby} onChange={e=>setForm({...form,price_per_baby:e.target.value as any})}/></label><label className="span2">Note interne<textarea rows={4} value={form.internal_notes} onChange={e=>setForm({...form,internal_notes:e.target.value})}/></label></form></Modal>}'''
s,n=re.subn(r'function EventModal\(\{clients,event,onClose,onSaved\}:any\).*?(?=function ClientModal)',new_modal+'\n',s,count=1,flags=re.S)
if n!=1:raise SystemExit('EventModal non trovato')
old='''<div className="ingredientImpactRecipe" key={r.id}><div><strong>{r.name}</strong>{r.category&&<small>{r.category}</small>}</div></div>'''
new='''<div className="ingredientImpactRecipe" key={r.id}><span className="ingredientRecipeInitial" aria-hidden="true">{(r.name||'?').trim().charAt(0).toLocaleUpperCase('it-IT')}</span><div><strong>{r.name}</strong>{r.category&&<small>{r.category}</small>}</div></div>'''
if old in s:s=s.replace(old,new,1)
page.write_text(s)
css=Path('app/event-form.css');c=css.read_text();block='''\n.eventPriceRow{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px}.eventPriceRow label{min-width:0}.eventPriceRow input{box-sizing:border-box;width:100%;height:48px;min-height:48px;max-height:48px;border-radius:10px}.eventPriceRow input[readonly]{background:var(--soft);color:var(--ink);font-weight:700}.eventPriceRow label:last-child input{color:var(--accent-dark);font-size:16px}@media(max-width:800px){.eventPriceRow{grid-template-columns:1fr}}\n'''
if '.eventPriceRow' not in c:css.write_text(c+block)
